package com.resumeanalyzer.repository;
import com.resumeanalyzer.dto.ResumeHistoryDto; import com.resumeanalyzer.entity.Resume; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.List; import java.util.Optional;
public interface ResumeRepository extends JpaRepository<Resume,Long> { Optional<Resume> findByIdAndUserId(Long id,Long userId); Optional<Resume> findTopByUserIdOrderByUploadedAtDesc(Long userId); @Query("select new com.resumeanalyzer.dto.ResumeHistoryDto(r.id, r.fileName, r.uploadedAt) from Resume r where r.user.id = :userId order by r.uploadedAt desc") List<ResumeHistoryDto> findHistoryByUserId(@Param("userId") Long userId); }
